import{_ as a,o,c as i,a2 as l}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"12.2 灭火方法与灭火器使用","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/12-chapter-12-dian-qi-fang-huo-fang-bao-yu-chu-dian-ji-jiu/12-2-mie-huo-fang-fa-yu-mie-huo-qi-shi-yong.md","filePath":"electrician/low-voltage-electrician/12-chapter-12-dian-qi-fang-huo-fang-bao-yu-chu-dian-ji-jiu/12-2-mie-huo-fang-fa-yu-mie-huo-qi-shi-yong.md","lastUpdated":1793096070000}'),r={name:"electrician/low-voltage-electrician/12-chapter-12-dian-qi-fang-huo-fang-bao-yu-chu-dian-ji-jiu/12-2-mie-huo-fang-fa-yu-mie-huo-qi-shi-yong.md"};function n(e,t,s,d,g,h){return o(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="_12-2-灭火方法与灭火器使用" tabindex="-1">12.2 灭火方法与灭火器使用 <a class="header-anchor" href="#_12-2-灭火方法与灭火器使用" aria-label="Permalink to &quot;12.2 灭火方法与灭火器使用&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>电气火灾灭火有一条铁律:<strong>先断电</strong>,断电后按普通火灾处理;不能断电时,只能用<strong>不导电</strong>的灭火器。这一节掌握灭火器的选择和使用(必考)。</p><h2 id="一、电气火灾灭火的原则" tabindex="-1">一、电气火灾灭火的原则 <a class="header-anchor" href="#一、电气火灾灭火的原则" aria-label="Permalink to &quot;一、电气火灾灭火的原则&quot;">​</a></h2><ol><li><strong>首先切断电源</strong>;</li><li>断电后可用水、泡沫等常规方式灭火(已无电危险);</li><li><strong>不能断电</strong>时,用<strong>不导电的灭火器</strong>带电灭火;</li><li>带电灭火时,人与带电体保持<strong>安全距离</strong>,灭火器喷嘴不接触带电体。</li></ol><blockquote><p>⚠️ 判断题高频:<strong>未断电的电气火灾,严禁用导电的灭火剂(水、泡沫)直接扑救</strong>,否则会触电。</p></blockquote><h2 id="二、常用灭火器对比-电气火灾用什么" tabindex="-1">二、常用灭火器对比(电气火灾用什么) <a class="header-anchor" href="#二、常用灭火器对比-电气火灾用什么" aria-label="Permalink to &quot;二、常用灭火器对比(电气火灾用什么)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>灭火器</th><th>能否用于带电电气火灾</th><th>说明</th></tr></thead><tbody><tr><td><strong>干粉灭火器</strong></td><td>✅ 能(不导电)</td><td>扑救电气火灾的主要选择</td></tr><tr><td><strong>二氧化碳灭火器</strong></td><td>✅ 能(不导电,不留残渣)</td><td>精密设备、带电场所也可用</td></tr><tr><td><strong>水</strong></td><td>❌ 不能(导电)</td><td>断电后可用</td></tr><tr><td><strong>泡沫灭火器</strong></td><td>❌ 不能(导电,含水分)</td><td>断电后可用</td></tr></tbody></table><blockquote><p>💡 记忆:<strong>带电火,用&quot;干粉、二氧化碳&quot;;水、泡沫要等断电再用</strong>。</p></blockquote><h2 id="三、干粉灭火器的使用方法-四步" tabindex="-1">三、干粉灭火器的使用方法(四步) <a class="header-anchor" href="#三、干粉灭火器的使用方法-四步" aria-label="Permalink to &quot;三、干粉灭火器的使用方法(四步)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>提(提起灭火器) → 拔(拔掉保险销) → 握(握住喷管) → 压(压下压把喷射)</span></span></code></pre></div><p>口诀:<strong>&quot;一提、二拔、三握、四压&quot;</strong>:</p><ol><li>提起灭火器,上下晃动让干粉松动;</li><li><strong>拔掉保险销</strong>;</li><li>一手<strong>握住喷管</strong>,对准火焰<strong>根部</strong>;</li><li><strong>压下压把</strong>,站在<strong>上风方向</strong>,对准火焰根部左右扫射。</li></ol><blockquote><p>⚠️ 判断题常考:喷射应<strong>对准火焰根部</strong>、站在<strong>上风方向</strong>。</p></blockquote><h2 id="四、电气灭火的安全要求" tabindex="-1">四、电气灭火的安全要求 <a class="header-anchor" href="#四、电气灭火的安全要求" aria-label="Permalink to &quot;四、电气灭火的安全要求&quot;">​</a></h2><ul><li>带电灭火保持安全距离,穿绝缘鞋、戴绝缘手套;</li><li>灭火器喷射不要直接喷向带电体近旁的人;</li><li>火灾扑灭后要<strong>彻底断电、检查</strong>,防止复燃;</li><li>无法控制时,立即<strong>报警(119)并疏散人员</strong>。</li></ul><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 电气火灾先断电,断电后任何灭火方法都可用。</li><li>✅ 带电灭火用<strong>干粉、二氧化碳</strong>;水、泡沫<strong>导电不能用</strong>。</li><li>✅ 干粉灭火器口诀:&quot;一提二拔三握四压&quot;,对准火焰根部、站上风。</li><li>⚠️ 易混点:泡沫灭火器虽然能灭油火,但<strong>含水分、导电</strong>,电气火灾不能用。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>先断电,断电后随便灭;不断电只能用不导电灭火器。</li><li>带电灭火选干粉、二氧化碳。</li><li>干粉灭火器:一提二拔三握四压,对准根部、站上风。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(判断)电气设备着火时,应先切断电源再灭火。( )</li><li>(单选)带电电气火灾,不能使用的灭火剂是()。 A. 干粉　B. 二氧化碳　C. 水　D. 1211</li><li>(判断)泡沫灭火器可用于带电的电气火灾。( )</li><li>(单选)干粉灭火器使用时应对准火焰的()。 A. 上部　B. 中部　C. 根部　D. 任意部位</li><li>(判断)使用灭火器灭火时,应站在上风方向。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。电气火灾先断电再灭火。</li><li><strong>C</strong>。水导电,不能用于带电火灾。</li><li><strong>×</strong>。泡沫含水分、导电,不能用于带电电气火灾。</li><li><strong>C</strong>。对准火焰根部喷射。</li><li><strong>√</strong>。站上风方向,避免被火焰和烟气伤害。</li></ol></details>',23)])])}const p=a(r,[["render",n]]);export{c as __pageData,p as default};
